#!/usr/bin/env bash
# Generate templates/<role>/scion-agent.yaml from the skill sets below.
#
# The generated files are committed. Re-run this script after changing a skill set,
# adding an adapted skill under skills/, or bumping UPSTREAM_SHA, and commit the result.
#
# Skill sources (all delivered as pure URIs in committed templates):
#   - adapted (skills/<name>/ exists in this repo)      -> gh://scion-frontiers/scion-pstack/<name>
#   - cursor-team-kit (deslop, control-ui, control-cli) -> SHA-pinned tree URI into cursor/plugins
#   - everything else from upstream pstack              -> SHA-pinned tree URI into cursor/plugins
#
# Usage:
#   bash build.sh            # rewrite templates/*/scion-agent.yaml (pure URIs)
#   bash build.sh --check    # exit 1 if committed templates, schema parity, or --bundle lints fail
#   bash build.sh --bundle DIR
#                            # write self-contained templates to DIR with every skill copied
#                            # in locally (for hubs without GitHub / GH_SCION_FRONTIERS access)
set -euo pipefail

ROOT="$(cd "$(dirname "$0")" && pwd)"
REPO_URI="gh://scion-frontiers/scion-pstack"
UPSTREAM_SHA="bf0c7cd80abdbf7fe47b634978a7d1b4071f71a7"
UPSTREAM_DIR="$ROOT/upstream/pstack-bf0c7cd"
URI_BASE="https://github.com/cursor/plugins/tree/$UPSTREAM_SHA/pstack/skills"
TEAMKIT_DIR="$ROOT/upstream/cursor-team-kit-bf0c7cd"
TEAMKIT_URI_BASE="https://github.com/cursor/plugins/tree/$UPSTREAM_SHA/cursor-team-kit/skills"
TEAMKIT="deslop control-ui control-cli"
DROPPED="make-bot-ui ketchup-video"
LEAD_ONLY="setup-pstack automate-me poteto-help"
EXTERNAL_UNSHIPPED="verify-this"
PLATFORM_SKILLS="git-operations team-creation software-engineering-process"

MODE=write
BUNDLE=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --check) MODE=check ;;
    --bundle)
      [[ $# -ge 2 && -n "${2:-}" ]] || { echo "--bundle requires a destination directory" >&2; exit 2; }
      MODE=bundle; BUNDLE="$2"; shift ;;
    *) echo "unknown arg: $1" >&2; exit 2 ;;
  esac
  shift
done

PRINCIPLES=$(cd "$UPSTREAM_DIR/skills" && LC_ALL=C ls -d principle-* | LC_ALL=C sort)

all_skills() {
  { ls "$UPSTREAM_DIR/skills"; ls "$ROOT/skills"; } | LC_ALL=C sort -u | grep -vxE "${DROPPED// /|}"
}

skills_for() {
  case "$1" in
    pstack-lead)   all_skills; printf '%s\n' $TEAMKIT ;;
    pstack-agent)  all_skills | grep -vxE "${LEAD_ONLY// /|}"; printf '%s\n' $TEAMKIT ;;
    pstack-reviewer)
      printf '%s\n' pstack-scion-runtime benchmark-checklist in-your-own-words interrogate \
        arena architect reflect show-me-your-work how why unslop technical-writing \
        typescript-best-practices blast-radius statechart control-ui control-cli $PRINCIPLES ;;
    pstack-comment-sicko) printf '%s\n' pstack-scion-runtime why ;;
    *) echo "no skill set for $1" >&2; exit 1 ;;
  esac
}

description_for() {
  case "$1" in
    pstack-lead) echo "pstack lead: poteto-mode always on; routes requests to playbooks, delegates, reviews, replies" ;;
    pstack-agent) echo "pstack worker: brief-driven code delegate, PR owner, arena candidate, stacker, or babysitter in poteto style" ;;
    pstack-reviewer) echo "pstack read-only panel member: interrogate/architect/arena judge, explainer, verifier, trail reviewer" ;;
    pstack-comment-sicko) echo "pstack Comment Sicko: hunts comments on its own branch, flags MUST KILL refactors" ;;
  esac
}

src_of() {
  if   [[ -d "$ROOT/skills/$1" ]];         then echo "$ROOT/skills/$1"
  elif [[ -d "$TEAMKIT_DIR/skills/$1" ]];  then echo "$TEAMKIT_DIR/skills/$1"
  elif [[ -d "$UPSTREAM_DIR/skills/$1" ]]; then echo "$UPSTREAM_DIR/skills/$1"
  else echo "missing skill $1" >&2; return 1
  fi
}

# Print "<kind> <name>" per skill, grouped (adapted, teamkit, upstream) and sorted within each group.
classify() {
  local s
  for s in $(skills_for "$1"); do
    src_of "$s" >/dev/null || exit 1
    if   [[ -d "$ROOT/skills/$s" ]];         then echo "0 adapted $s"
    elif [[ -d "$TEAMKIT_DIR/skills/$s" ]];  then echo "1 teamkit $s"
    else echo "2 upstream $s"
    fi
  done | LC_ALL=C sort -u -k1,1n -k3,3 | cut -d' ' -f2-
}

render_yaml() {
  local tpl="$1" kind name last=""
  echo 'schema_version: "1"'
  echo "description: \"$(description_for "$tpl")\""
  echo "agent_instructions: agents.md"
  echo "# No system_prompt: the harness default prompt is kept (see LEARNINGS L11)."
  echo "# Harness and model are chosen per spawn from pstack-models.yaml (see pstack-scion-runtime)."
  [[ "$tpl" == pstack-lead ]] && echo "model: extra-large"
  echo "#"
  echo "# Generated by build.sh; edit the skill sets there, then re-run it."
  echo "skills:"
  while read -r kind name; do
    if [[ "$kind" != "$last" ]]; then
      case "$kind" in
        adapted)  echo "  # Adapted for Scion, from this repo's skills/ (diffs/ has each fork's diff against upstream)." ;;
        teamkit)  echo "  # Unchanged cursor-team-kit skills that pstack cites, pinned to cursor/plugins@${UPSTREAM_SHA:0:7}." ;;
        upstream) echo "  # Unchanged upstream pstack skills, pinned to cursor/plugins@${UPSTREAM_SHA:0:7}." ;;
      esac
      last="$kind"
    fi
    case "$kind" in
      adapted)  echo "  - uri: \"$REPO_URI/$name\"" ;;
      teamkit)  echo "  - uri: \"$TEAMKIT_URI_BASE/$name\"" ;;
      upstream) echo "  - uri: \"$URI_BASE/$name\"" ;;
    esac
  done < <(classify "$tpl")
}

bundle_into() {
  local out="$1" quiet="${2:-0}" dir tpl dest kind name
  for dir in "$ROOT"/templates/*/; do
    tpl=$(basename "$dir")
    dest="$out/$tpl"
    rm -rf "$dest"; mkdir -p "$dest/skills"
    cp "$dir/agents.md" "$dest/agents.md"
    render_yaml "$tpl" | sed '/^skills:/,$d' > "$dest/scion-agent.yaml"
    while read -r kind name; do
      rsync -a --delete --exclude PORT-NOTES.md --exclude node_modules --exclude 'scripts/test' \
        "$(src_of "$name")/" "$dest/skills/$name/"
    done < <(classify "$tpl")
    [[ "$quiet" == "1" ]] || echo "$tpl: bundled $(ls -1 "$dest/skills" | wc -l | tr -d ' ') skills into $dest"
  done
}

# Extract "<section>.<key>" entries from the "# pstack-models.yaml" fenced YAML block (#8).
models_schema_keys() {
  awk '
    /^```yaml$/ { in_yaml=1; is_models=0; sec="top"; next }
    in_yaml && /^```$/ { if (is_models) exit; in_yaml=0; next }
    in_yaml && /^# pstack-models\.yaml([. ]|$)/ { is_models=1; next }
    is_models {
      line = $0
      sub(/[[:space:]]*#.*/, "", line)
      if (line ~ /^[a-z][a-z0-9-]*:[[:space:]]*$/) {
        sub(/:.*/, "", line)
        sec = line
      } else if (line ~ /^[a-z][a-z0-9-]*:/) {
        sub(/:.*/, "", line)
        print "top." line
      } else if (line ~ /^  [a-z][a-z0-9-]*:/) {
        sub(/^  /, "", line)
        sub(/:.*/, "", line)
        print sec "." line
      }
    }
  ' "$1" | LC_ALL=C sort -u
}

check_models_schema() {
  local runtime_md="$ROOT/skills/pstack-scion-runtime/SKILL.md"
  local setup_md="$ROOT/skills/setup-pstack/SKILL.md"
  local runtime_keys setup_keys
  runtime_keys=$(models_schema_keys "$runtime_md")
  setup_keys=$(models_schema_keys "$setup_md")
  if ! grep -q '^roles\.' <<<"$runtime_keys" || ! grep -q '^panels\.' <<<"$runtime_keys"; then
    echo "pstack-scion-runtime/SKILL.md: missing roles or panels in pstack-models.yaml block" >&2
    return 1
  fi
  if ! grep -q '^roles\.' <<<"$setup_keys" || ! grep -q '^panels\.' <<<"$setup_keys"; then
    echo "setup-pstack/SKILL.md: missing roles or panels in pstack-models.yaml block" >&2
    return 1
  fi
  if ! diff -u -L "pstack-scion-runtime/SKILL.md" -L "setup-pstack/SKILL.md" \
      <(printf '%s\n' "$runtime_keys") <(printf '%s\n' "$setup_keys"); then
    echo "pstack-models.yaml schema keys differ between pstack-scion-runtime and setup-pstack" >&2
    return 1
  fi
}

# Lint bundled templates for unshipped skill references and broken relative links (#11).
check_bundle_refs() {
  local bundle_root="$1" bad=0 tpl_dir tpl tpl_real shipped allowed all_known runtime_ok
  all_known=$( { ls "$UPSTREAM_DIR/skills"; ls "$TEAMKIT_DIR/skills"; ls "$ROOT/skills"; } | LC_ALL=C sort -u | tr '\n' ' ' )
  runtime_ok=$( { all_skills; printf '%s\n' $TEAMKIT $DROPPED $EXTERNAL_UNSHIPPED; } | LC_ALL=C sort -u | tr '\n' ' ' )

  for tpl_dir in "$bundle_root"/*/; do
    tpl_dir="${tpl_dir%/}"
    tpl=$(basename "$tpl_dir")
    tpl_real=$(cd "$tpl_dir" && pwd -P)
    shipped=$(ls -1 "$tpl_dir/skills" | tr '\n' ' ')
    allowed="$EXTERNAL_UNSHIPPED"
    [[ "$tpl" != "pstack-lead" ]] && allowed="$allowed $LEAD_ONLY"
    # Read-only reviewers run under caller briefs; poteto-mode's Subagents effort rule is mirrored in pstack-scion-runtime §1.
    [[ "$tpl" == "pstack-reviewer" ]] && allowed="$allowed poteto-mode"

    local md_files=() f
    while IFS= read -r f; do md_files+=("$f"); done < <(find "$tpl_dir" -name '*.md' | LC_ALL=C sort)

    if ! awk \
      -v tpl="$tpl" \
      -v base="$tpl_dir/" \
      -v tpl_real="$tpl_real" \
      -v shipped="$shipped" \
      -v allowed="$allowed" \
      -v runtime_ok="$runtime_ok" \
      -v all_known="$all_known" \
      -v platform="$PLATFORM_SKILLS" \
      '
      BEGIN {
        n = split(shipped, a, " ");    for (i=1; i<=n; i++) if (a[i]!="") is_shipped[a[i]] = 1
        n = split(allowed, a, " ");    for (i=1; i<=n; i++) if (a[i]!="") is_allowed[a[i]] = 1
        n = split(runtime_ok, a, " "); for (i=1; i<=n; i++) if (a[i]!="") is_runtime_ok[a[i]] = 1
        n = split(all_known, a, " ");  for (i=1; i<=n; i++) if (a[i]!="") is_known[a[i]] = 1
        n = split(platform, a, " ");   for (i=1; i<=n; i++) if (a[i]!="") is_platform[a[i]] = 1
        bad = 0
      }
      FNR == 1 {
        in_fence = 0; fence_char = ""; fence_len = 0
        rel = FILENAME
        if (index(rel, base) == 1) rel = substr(rel, length(base) + 1)
        is_runtime_doc = (rel == "skills/pstack-scion-runtime/SKILL.md")
        is_skill_root = (rel ~ /^skills\/[^\/]+\/[^\/]+$/)
        is_skill_sub1 = (rel ~ /^skills\/[^\/]+\/[^\/]+\/[^\/]+$/)
        dir_of_file = FILENAME
        sub(/\/[^\/]+$/, "", dir_of_file)
      }
      function is_plat(tok) {
        return (tok ~ /^scion-/) || (tok in is_platform)
      }
      function check_ref(tok, strict_local, require_known,   ok, key) {
        if (tok == "") return
        if (!strict_local && is_plat(tok)) return
        if (!require_known && !(tok in is_known)) return
        if (strict_local) {
          ok = (tok in is_shipped)
        } else if (is_runtime_doc) {
          ok = (tok in is_runtime_ok)
        } else {
          ok = (tok in is_shipped) || (tok in is_allowed)
        }
        if (!ok) {
          key = rel ":" FNR ":" tok
          if (!(key in reported)) {
            reported[key] = 1
            printf "%s: %s:%d references unshipped skill '\''%s'\''\n", tpl, rel, FNR, tok > "/dev/stderr"
            bad = 1
          }
        }
      }
      {
        line = $0
        if (!in_fence && match(line, /^ ? ? ?(```+|~~~+)/)) {
          s = substr(line, RSTART, RLENGTH); sub(/^ +/, "", s)
          in_fence = 1; fence_char = substr(s, 1, 1); fence_len = length(s)
        } else if (in_fence && match(line, /^ ? ? ?(```+|~~~+) *$/)) {
          s = substr(line, RSTART, RLENGTH); sub(/^ +/, "", s); sub(/ +$/, "", s)
          if (substr(s, 1, 1) == fence_char && length(s) >= fence_len) in_fence = 0
        }

        # 1. Backtick skill tokens: `foo`, `/foo`, `foo/SKILL.md`
        s = line
        while (match(s, /`\/?[a-z][a-z0-9-]+(\/SKILL\.md)?`/)) {
          tok = substr(s, RSTART + 1, RLENGTH - 2)
          has_skill_md = (tok ~ /\/SKILL\.md$/)
          sub(/^\//, "", tok); sub(/\/SKILL\.md$/, "", tok)
          check_ref(tok, 0, has_skill_md)
          s = substr(s, RSTART + RLENGTH)
        }

        # 2. Bold skill tokens: **foo**, **/foo**
        s = line
        while (match(s, /\*\*\/?[a-z][a-z0-9-]+\*\*/)) {
          tok = substr(s, RSTART + 2, RLENGTH - 4)
          sub(/^\//, "", tok)
          check_ref(tok, 0, 0)
          s = substr(s, RSTART + RLENGTH)
        }

        # 3. Slash skill tokens: /foo (outside URLs/paths)
        s = line
        while (match(s, /(^|[^A-Za-z0-9_.:\/-])\/[a-z][a-z0-9-]+([^A-Za-z0-9_\/-]|$)/)) {
          seg = substr(s, RSTART, RLENGTH)
          off = RSTART
          match(seg, /\/[a-z][a-z0-9-]+/)
          tok = substr(seg, RSTART + 1, RLENGTH - 1)
          adv = off + RSTART + RLENGTH - 1
          check_ref(tok, 0, 0)
          s = substr(s, adv)
        }

        # 4. Cross-skill relative paths inside skills/ (must resolve to a shipped skill)
        if (is_skill_root) {
          s = line
          while (match(s, /\.\.\/[a-z][a-z0-9-]+\//)) {
            tok = substr(s, RSTART + 3, RLENGTH - 4)
            check_ref(tok, 1, 1)
            s = substr(s, RSTART + RLENGTH)
          }
        } else if (is_skill_sub1) {
          s = line
          while (match(s, /\.\.\/\.\.\/[a-z][a-z0-9-]+\//)) {
            tok = substr(s, RSTART + 6, RLENGTH - 7)
            check_ref(tok, 1, 1)
            s = substr(s, RSTART + RLENGTH)
          }
        }
        s = line
        while (match(s, /skills\/[a-z][a-z0-9-]+(\/|[^A-Za-z0-9_-]|$)/)) {
          seg = substr(s, RSTART + 7, RLENGTH - 7)
          sub(/[^a-z0-9-].*$/, "", seg)
          check_ref(seg, 0, 0)
          s = substr(s, RSTART + 7)
        }

        # 5. Explicit prose: "the **foo** principle skill" / "the **foo** skill"
        s = line
        while (match(s, /the (\*\*[a-z][a-z0-9-]+\*\*|`\/?[a-z][a-z0-9-]+`) principle skill/)) {
          seg = substr(s, RSTART + 4, RLENGTH - 20)
          gsub(/[*`\/]/, "", seg)
          check_ref("principle-" seg, 1, 1)
          s = substr(s, RSTART + RLENGTH)
        }
        s = line
        while (match(s, /the (\*\*[a-z][a-z0-9-]+\*\*|`\/?[a-z][a-z0-9-]+`) skill/)) {
          seg = substr(s, RSTART + 4, RLENGTH - 10)
          gsub(/[*`\/]/, "", seg)
          check_ref(seg, 0, 1)
          s = substr(s, RSTART + RLENGTH)
        }

        # 6. Relative Markdown links outside code fences must exist within the bundle template
        if (!in_fence) {
          s = line
          while (match(s, /\[[^\]]+\]\([^)#?[:space:]]+/)) {
            seg = substr(s, RSTART, RLENGTH)
            sub(/^\[[^\]]+\]\(/, "", seg)
            if (seg !~ /^(https?:|mailto:|gh:|scion:|\/)/ && seg !~ /[<>]/) {
              if (seg ~ /["$`\\]/) {
                printf "%s: %s:%d invalid characters in relative link '\''%s'\''\n", tpl, rel, FNR, seg > "/dev/stderr"
                bad = 1
              } else {
                cmd = "target=\"" dir_of_file "/" seg "\"; test -e \"$target\" && dir=$(cd \"$(dirname \"$target\")\" 2>/dev/null && pwd -P) && case \"$dir\" in \"" tpl_real "\"|\"" tpl_real "\"/*) exit 0 ;; *) exit 1 ;; esac"
                if (system(cmd) != 0) {
                  printf "%s: %s:%d broken relative link '\''%s'\''\n", tpl, rel, FNR, seg > "/dev/stderr"
                  bad = 1
                }
              }
            }
            s = substr(s, RSTART + RLENGTH)
          }
        }
      }
      END { exit bad }
      ' "${md_files[@]}"; then
      bad=1
    fi
  done
  return "$bad"
}

case "$MODE" in
  write)
    for dir in "$ROOT"/templates/*/; do
      tpl=$(basename "$dir")
      render_yaml "$tpl" > "$dir/scion-agent.yaml"
      rm -rf "${dir}skills"
      echo "$tpl: $(grep -c '^  - uri:' "$dir/scion-agent.yaml") URI skills"
    done ;;
  bundle)
    bundle_into "$BUNDLE" 0 ;;
  check)
    stale=0
    for dir in "$ROOT"/templates/*/; do
      tpl=$(basename "$dir")
      if ! diff -u "$dir/scion-agent.yaml" <(render_yaml "$tpl"); then stale=1; fi
      if [[ -d "${dir}skills" ]]; then
        echo "$tpl: unexpected committed skills/ directory (committed templates must be pure URIs)" >&2
        stale=1
      fi
      extra_entries=$(LC_ALL=C ls -A "$dir" | grep -vxE 'agents\.md|scion-agent\.yaml' || true)
      if [[ -n "$extra_entries" ]]; then
        echo "$tpl: unexpected entries in template dir: $extra_entries" >&2
        stale=1
      fi
    done

    tmp_bundle=$(mktemp -d)
    trap 'rm -rf "$tmp_bundle"' EXIT
    bundle_into "$tmp_bundle" 1
    for dir in "$ROOT"/templates/*/; do
      tpl=$(basename "$dir")
      if grep -qE '^(skills:|  - uri:)' "$tmp_bundle/$tpl/scion-agent.yaml"; then
        echo "$tpl: --bundle scion-agent.yaml still contains external skill URIs" >&2
        stale=1
      fi
      expected_count=$(skills_for "$tpl" | LC_ALL=C sort -u | wc -l | tr -d ' ')
      actual_count=$(ls -1 "$tmp_bundle/$tpl/skills" | wc -l | tr -d ' ')
      if [[ "$expected_count" != "$actual_count" ]]; then
        echo "$tpl: --bundle skill count mismatch (expected $expected_count, got $actual_count)" >&2
        stale=1
      fi
      for s in $(skills_for "$tpl" | LC_ALL=C sort -u); do
        if [[ ! -s "$tmp_bundle/$tpl/skills/$s/SKILL.md" ]]; then
          echo "$tpl: --bundle missing or empty SKILL.md for $s" >&2
          stale=1
        fi
      done
    done
    leaked=$(find "$tmp_bundle" \( -name PORT-NOTES.md -o -name node_modules -o -path '*/scripts/test' \) -print -quit)
    if [[ -n "$leaked" ]]; then
      echo "--bundle leaked excluded file or directory: $leaked" >&2
      stale=1
    fi
    if ! check_models_schema; then
      stale=1
    fi
    if ! check_bundle_refs "$tmp_bundle"; then
      stale=1
    fi
    [[ $stale -eq 0 ]] && echo "templates and bundle check are up to date" || { echo "stale or invalid: run bash build.sh" >&2; exit 1; } ;;
esac
